@Component
export struct FoldSettingsPanel {
  @State private opened: boolean = false

  @Builder
  private SettingsDetail() {
    Column() {
      Row() {
        Text('Settings details')
        SymbolGlyph($r('sys.symbol.chevron_down'))
          .rotate({ angle: this.opened ? 0 : 180 })
      }
      .onClick(() => {
        this.opened = !this.opened
      })

      if (this.opened) {
        Text('Advanced settings')
      }
    }
  }

  build() {
    this.SettingsDetail()
  }
}

